43: 
44: /* the max number of parameters */
45: #define PARAM_LEN 20
46: 
47: #define TRY_CDF(__fcall__)\
48: {int errval; errval=__fcall__;netCDF_handle_error(errval);}
49: 
50: void netCDF_handle_error(int status)
51: {
52:   char errstring[240];
53: 
54:   if (status != NC_NOERR) {
55:     sprintf(errstring,"netCDF error: %s",nc_strerror(status));
56:     fatal(errstring);
57:   }
