61: /****************************************************************************
62:  *
63:  *                   Procedure netCDF_init_file
64:  *
65:  * Arguments: details: pointer to detail_type
66:  *              cell: pointer to cell type
67:  *          num_orbs: int
68:  *          walsh_step: int
69:  *
70:  * Returns: none
71:  *
72:  * Action:  Writes header information into a netCDF file.
73:  *
74:  ****************************************************************************/
75: void netCDF_init_file(detail_type *details,cell_type *cell,int num_orbs,
76:                       int walsh_step)
77: {
78:   int i,j,itab,jtab;
79:   char outname[240];
80:   int fileid;
81:   int dim_array[10],count_array[10];
82:   int symb_var_ID,pos_var_ID,param_var_ID;
83:   int kpoints_ID,kpoint_weights_ID,num_electrons_ID;
84:   int lattice_ID;
85:   real temp_vect[PARAM_LEN];
86: 
87:   if( !details->do_netCDF )
88:     FATAL_BUG("init_netCDF called without CDF writing on.");
89: 
90:   /* get space for the netCDF_info structure */
91:   details->netCDF_info = (netCDF_info_type *)my_calloc(1,sizeof(netCDF_info_type));
92: 
93:   if( details->walsh_details.num_steps > 1){
94:     sprintf(outname,"%s.step%d.nCDF",walsh_step,details->filename);
95:   }
96:   else{
97:     sprintf(outname,"%s.nCDF",details->filename);
98:   }
99: 
100:   /* create (or overwrite) the CDF file */
101:   TRY_CDF(nc_create(outname,NC_CLOBBER,&fileid));
102: 
103:   /* set the pointer in details */
104:   details->netCDF_info->file_ID = fileid;
105: 
106: 
107:   /* write the definitions */
108:   TRY_CDF(nc_def_dim(fileid,"num_orbs",
109:                      (size_t)num_orbs,
110:                      &details->netCDF_info->num_orbs_ID));
111:   TRY_CDF(nc_def_dim(fileid,"num_kpoints",
112:                      (size_t)details->num_KPOINTS,
113:                      &details->netCDF_info->num_KPOINTS_ID));
114:   TRY_CDF(nc_def_dim(fileid,"tot_num_orbs",
115:                      (size_t)details->num_KPOINTS*num_orbs,
116:                      &details->netCDF_info->tot_num_orbs_ID));
117:   TRY_CDF(nc_def_dim(fileid,"num_atoms",
118:                      (size_t)cell->num_atoms,
119:                      &details->netCDF_info->num_atoms_ID));
120:   TRY_CDF(nc_def_dim(fileid,"num_dim",
121:                      (size_t)cell->dim,
122:                      &details->netCDF_info->num_dim_ID));
123:   TRY_CDF(nc_def_dim(fileid,"name_length",
124:                      (size_t)ATOM_SYMB_LEN,
125:                      &details->netCDF_info->name_len_ID));
126:   TRY_CDF(nc_def_dim(fileid,"param_length",
127:                      (size_t)PARAM_LEN,
128:                      &details->netCDF_info->param_len_ID));
129: 
130:   /* it's kind of dumb that we have to do this */
131:   TRY_CDF(nc_def_dim(fileid,"space_dim",
132:                      (size_t)3,
133:                      &details->netCDF_info->space_dim_ID));
134: 
135: 
136:   /* start with the atoms */
137:   dim_array[0] = details->netCDF_info->num_atoms_ID;
138:   dim_array[1] = details->netCDF_info->name_len_ID;
139:   TRY_CDF(nc_def_var(details->netCDF_info->file_ID,
140:                      "Atom_Symbols",NC_CHAR,2,(int *)dim_array,
141:                      &symb_var_ID));
142:   dim_array[0] = details->netCDF_info->num_atoms_ID;
143:   dim_array[1] = details->netCDF_info->param_len_ID;
144:   TRY_CDF(nc_def_var(details->netCDF_info->file_ID,
145:                      "Atomic_Parameters",NC_DOUBLE,
146:                      2,(int *)dim_array,&param_var_ID));
147:   dim_array[0] = details->netCDF_info->num_atoms_ID;
148:   dim_array[1] = details->netCDF_info->space_dim_ID;
149:   TRY_CDF(nc_def_var(details->netCDF_info->file_ID,
150:                      "Atomic_Positions",NC_DOUBLE,
151:                      2,(int *)dim_array,&pos_var_ID));
152:   dim_array[0] = details->netCDF_info->num_dim_ID;
153:   dim_array[1] = details->netCDF_info->space_dim_ID;
154:   TRY_CDF(nc_def_var(details->netCDF_info->file_ID,
155:                      "Lattice_Vects",NC_DOUBLE,
156:                      2,(int *)dim_array,&lattice_ID));
157: 
158:   dim_array[0] = details->netCDF_info->num_KPOINTS_ID;
159:   dim_array[1] = details->netCDF_info->space_dim_ID;
160:   TRY_CDF(nc_def_var(details->netCDF_info->file_ID,
161:                      "Kpoint_locs",NC_DOUBLE,
162:                      2,(int *)dim_array,&kpoints_ID));
163:   dim_array[0] = details->netCDF_info->num_KPOINTS_ID;
164:   TRY_CDF(nc_def_var(details->netCDF_info->file_ID,
165:                      "Kpoint_weights",NC_DOUBLE,
166:                      1,(int *)dim_array,&kpoint_weights_ID));
167: 
168:   /* number of electrons */
169:   TRY_CDF(nc_def_var(details->netCDF_info->file_ID,
170:                      "Num_Electrons",NC_DOUBLE,
171:                      0,(int *)dim_array,&num_electrons_ID));
172: 
173: 
174:   /* close define mode */
175:   TRY_CDF(nc_enddef(fileid));
176: 
177:   /****
178:     write header data
179:   ****/
180: 
181:   /* loop over atoms */
182:   for(i=0;i<cell->num_atoms;i++){
183: 
184:     /* write the symbol */
185:     dim_array[0] = i;
186:     dim_array[1] = 0;
187:     count_array[0] = 1;
188:     count_array[1] = ATOM_SYMB_LEN;
189:     TRY_CDF(nc_put_vara_text(details->netCDF_info->file_ID,symb_var_ID,
190:                              (size_t *)dim_array,(size_t *)count_array,
191:                              cell->atoms[i].symb));
192: 
193:     /* then the position */
194:     temp_vect[0] = cell->atoms[i].loc.x;
195:     temp_vect[1] = cell->atoms[i].loc.y;
196:     temp_vect[2] = cell->atoms[i].loc.z;
197:     dim_array[0] = i;
198:     dim_array[1] = 0;
199:     count_array[0] = 1;
200:     count_array[1] = 3;
201:     TRY_CDF(nc_put_vara_double(details->netCDF_info->file_ID,pos_var_ID,
202:                                (size_t *)dim_array,(size_t *)count_array,
203:                                (double *)temp_vect));
204: 
205:     /* build an array of the parameters */
206:     temp_vect[0] = (double)cell->atoms[i].at_number;
207:     temp_vect[1] = (double)cell->atoms[i].num_valence;
208:     temp_vect[2] = (double)cell->atoms[i].ns;
209:     temp_vect[3] = (double)cell->atoms[i].coul_s;
210:     temp_vect[4] = (double)cell->atoms[i].exp_s;
211:     temp_vect[5] = (double)cell->atoms[i].np;
212:     temp_vect[6] = (double)cell->atoms[i].coul_p;
213:     temp_vect[7] = (double)cell->atoms[i].exp_p;
214:     temp_vect[8] = (double)cell->atoms[i].nd;
215:     temp_vect[9] = (double)cell->atoms[i].coul_d;
216:     temp_vect[10] = (double)cell->atoms[i].exp_d;
217:     temp_vect[11] = (double)cell->atoms[i].coeff_d1;
218:     temp_vect[10] = (double)cell->atoms[i].exp_d2;
219:     temp_vect[13] = (double)cell->atoms[i].coeff_d2;
220:     temp_vect[14] = (double)cell->atoms[i].nf;
221:     temp_vect[15] = (double)cell->atoms[i].coul_f;
222:     temp_vect[16] = (double)cell->atoms[i].exp_f;
223:     temp_vect[17] = (double)cell->atoms[i].coeff_f1;
224:     temp_vect[18] = (double)cell->atoms[i].exp_f2;
225:     temp_vect[19] = (double)cell->atoms[i].coeff_f2;
226: 
227:     /* then write them */
228:     dim_array[0] = i;
229:     dim_array[1] = 0;
230:     count_array[0] = 1;
231:     count_array[1] = PARAM_LEN;
232:     TRY_CDF(nc_put_vara_double(details->netCDF_info->file_ID,param_var_ID,
233:                                (size_t *)dim_array,(size_t *)count_array,
234:                                (double *)temp_vect));
235:   }
236: 
237:   /* slap in the translation vectors */
238:   for(i=0;i<cell->dim;i++){
239:     itab = cell->tvects[i].begin;
240:     jtab = cell->tvects[i].end;
241:     temp_vect[0] = cell->atoms[jtab].loc.x-cell->atoms[itab].loc.x;
242:     temp_vect[1] = cell->atoms[jtab].loc.y-cell->atoms[itab].loc.y;
243:     temp_vect[2] = cell->atoms[jtab].loc.z-cell->atoms[itab].loc.z;
244: 
245:     dim_array[0] = i;
246:     dim_array[1] = 0;
247:     count_array[0] = 1;
248:     count_array[1] = 3;
249:     TRY_CDF(nc_put_vara_double(details->netCDF_info->file_ID,lattice_ID,
250:                                (size_t *)dim_array,(size_t *)count_array,
251:                                (double *)temp_vect));
252:   }
253: 
254:   /* and the k points */
255:   for(i=0;i<details->num_KPOINTS;i++){
256:     temp_vect[0] = details->K_POINTS[i].loc.x;
257:     temp_vect[1] = details->K_POINTS[i].loc.y;
258:     temp_vect[2] = details->K_POINTS[i].loc.z;
259:     dim_array[0] = i;
260:     dim_array[1] = 0;
261:     count_array[0] = 1;
262:     count_array[1] = 3;
263:     TRY_CDF(nc_put_vara_double(details->netCDF_info->file_ID,kpoints_ID,
264:                                (size_t *)dim_array,(size_t *)count_array,
265:                                (double *)temp_vect));
266:     count_array[0] = i;
267:     if( cell->dim > 0 ) temp_vect[0] = details->K_POINTS[i].weight;
268:     else temp_vect[0] = 1;
269:     TRY_CDF(nc_put_var1_double(details->netCDF_info->file_ID,
270:                                kpoint_weights_ID,
271:                                (size_t *)count_array,(double *)temp_vect));
272:   }
273: 
274:   TRY_CDF(nc_put_var1_double(details->netCDF_info->file_ID,
275:                              num_electrons_ID,
276:                              (size_t *)0,(double *)&cell->num_electrons));
277: 
278:   /* it's safe to write the other data now */
279: }
