282: /****************************************************************************
283:  *
284:  *                   Procedure netCDF_write_MOs
285:  *
286:  * Arguments: details: pointer to detail_type
287:  *           num_orbs: int
288:  *          prop_info: pointer to avg_prop_info_type
289:  *
290:  * Returns: none
291:  *
292:  * Action:  Writes orbital energies to netCDF file
293:  *
294:  ****************************************************************************/
295: void netCDF_write_MOs(detail_type *details,int num_orbs,
296:                       avg_prop_info_type *prop_info)
297: {
298:   int orbR_ID;
299:   int orbI_ID;
300:   int dim_array[10],count_array[10];
301:   size_t cell_dim;
302: 
303:   /* read out the dimension */
304:   TRY_CDF(nc_inq_dimlen(details->netCDF_info->file_ID,
305:                         details->netCDF_info->num_dim_ID,
306:                         (size_t *)&cell_dim));
307:   /****
308:     "allocate" the variables
309:   ****/
310: 
311:   /* switch to definition mode */
312:   TRY_CDF(nc_redef(details->netCDF_info->file_ID));
313: 
314:   /* coefficient arrays */
315:   dim_array[0] = details->netCDF_info->num_KPOINTS_ID;
316:   dim_array[1] = details->netCDF_info->num_orbs_ID;
317:   dim_array[2] = details->netCDF_info->num_orbs_ID;
318:   TRY_CDF(nc_def_var(details->netCDF_info->file_ID,
319:                      "Crystal_OrbitalsR",NC_FLOAT,
320:                      3,(int *)dim_array,&orbR_ID));
321:   /* only write imaginary coefficients if they are required */
322:   if( cell_dim > 0 ){
323:     TRY_CDF(nc_def_var(details->netCDF_info->file_ID,
324:                        "Crystal_OrbitalsI",NC_FLOAT,
325:                        3,(int *)dim_array,&orbI_ID));
326:   }
327:   /* close define mode */
328:   TRY_CDF(nc_enddef(details->netCDF_info->file_ID));
329: 
330:   /* now write the variables */
331:   dim_array[0] = 0;
332:   dim_array[1] = 0;
333:   dim_array[2] = 0;
334:   count_array[0] = details->num_KPOINTS;
335:   count_array[1] = num_orbs;
336:   count_array[2] = num_orbs;
337:   TRY_CDF(nc_put_vara_float(details->netCDF_info->file_ID,orbR_ID,
338:                              (size_t *)dim_array,(size_t *)count_array,
339:                              (float *)prop_info->orbs));
340:   if( cell_dim > 0 ){
341:     TRY_CDF(nc_put_vara_float(details->netCDF_info->file_ID,orbI_ID,
342:                               (size_t *)dim_array,(size_t *)count_array,
343:                               (float *)prop_info->orbsI));
344:   }
345: 
346: }
347: 
348: /****************************************************************************
349:  *
350:  *                   Procedure netCDF_write_Es
351:  *
352:  * Arguments: details: pointer to detail_type
353:  *           num_orbs: int
354:  *          prop_info: pointer to avg_prop_info_type
355:  *
356:  * Returns: none
357:  *
358:  * Action:  Writes header information into a netCDF file.
359:  *
360:  ****************************************************************************/
361: void netCDF_write_Es(detail_type *details,int num_orbs,
362:                      avg_prop_info_type *prop_info)
363: {
364:   int E_var_ID;
365:   int dim_array[10],count_array[10];
366: 
367:   TRY_CDF(nc_redef(details->netCDF_info->file_ID));
368:   dim_array[0] = details->netCDF_info->num_KPOINTS_ID;
369:   dim_array[1] = details->netCDF_info->num_orbs_ID;
370:   TRY_CDF(nc_def_var(details->netCDF_info->file_ID,
371:                      "Orbital_Energies",NC_FLOAT,
372:                      2,(int *)dim_array,&E_var_ID));
373:   /* close define mode */
374:   TRY_CDF(nc_enddef(details->netCDF_info->file_ID));
375: 
376:   dim_array[0] = 0;
377:   dim_array[1] = 0;
378:   count_array[0] = details->num_KPOINTS;
379:   count_array[1] = num_orbs;
380:   TRY_CDF(nc_put_vara_float(details->netCDF_info->file_ID,E_var_ID,
381:                              (size_t *)dim_array,(size_t *)count_array,
382:                              (float *)prop_info->energies));
383: 
384: }
