388: /****************************************************************************
389:  *
390:  *                   Procedure netCDF_close_file
391:  *
392:  * Arguments: details: pointer to detail_type
393:  *
394:  * Returns: none
395:  *
396:  * Action:  closes the net CDF file in 'details
397:  *
398:  ****************************************************************************/
399: void netCDF_close_file(detail_type *details)
400: {
